function MobileStandingRow({
	item,
	leagueSlug,
	onClick,
	dimmed,
}: {
	item: {
		id: string;
		name: string;
		image: string | null;
		playerId: string;
		score: number;
		matchCount: number;
		winCount: number;
		pointDiff: number;
		form: ("W" | "D" | "L")[] | undefined;
	};
	leagueSlug?: string;
	onClick?: () => void;
	dimmed?: boolean;
}) {
	const winPct = item.matchCount > 0 ? Math.round((item.winCount / item.matchCount) * 100) : 0;
	const streak = calculateStreak(item.form);

	return (
		<div
			className={cn(
				"flex items-center gap-2 bg-card px-1 py-3",
				leagueSlug && "cursor-pointer hover:bg-muted/50",
				dimmed && "opacity-40"
			)}
			onClick={onClick}
			data-testid={`standing-row-${item.id}`}
		>
			<StreakAvatar
				src={item.image}
				name={item.name}
				streak={streak}
				size={32}
				className="shrink-0 self-center"
			/>

			<div className="flex min-w-0 flex-1 flex-col gap-0.5">
