import { View, Text, StyleSheet } from "react-native";
import { Image } from "expo-image";
import { Colors } from "@/constants/theme";
import { useTheme } from "@/hooks/use-theme";

function getInitials(name: string) {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return "?";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

export function Avatar({ name, image, size = 32 }: { name: string; image?: string | null; size?: number }) {
  const theme = useTheme();
  if (image) {
    return <Image source={{ uri: image }} style={{ width: size, height: size, borderRadius: size / 2 }} />;
  }
  return (
    <View style={{ width: size, height: size, borderRadius: size / 2, backgroundColor: theme.primary, alignItems: "center", justifyContent: "center" }}>
      <Text style={{ color: theme.primaryForeground, fontSize: size * 0.4, fontWeight: "600" }}>{getInitials(name)}</Text>
    </View>
  );
}
```

Hmm, useTheme hook — let me check it. From explore: `use-theme.ts` returns Colors[scheme]. Good.

