	return (
		<View
			style={{
				width: size,
				height: size,
				borderRadius: size / 2,
				backgroundColor: theme.primary,
				alignItems: "center",
				justifyContent: "center",
			}}
		>
			<ThemedText type="smallBold" themeColor="primaryForeground" style={{ fontSize: size * 0.4 }}>
				{initials}
			</ThemedText>
		</View>
	);
}
